+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = "vaadin.launch-browser=false")
+class ContactBrowserTest {
+    @LocalServerPort
+    private int port;
+
+    @Test
+    void sendsAndGuardsNavigationInBrowser() {
+        try (Playwright playwright = Playwright.create();
+             Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                     .setHeadless(true).setArgs(java.util.List.of("--no-sandbox")))) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Contact"))).isVisible();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true)).click();
+            assertThat(page.getByText("Name is required", new Page.GetByTextOptions().setExact(true))).isVisible();
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Ada");
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("123");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Hello from Chromium");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("Ada");
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+            assertThat(page.getByText("Message sent", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true))).isDisabled();
+            assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("");
+            assertThat(page.getByText("Hello from Chromium", new Page.GetByTextOptions().setExact(true))).isVisible();
+            page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true)).fill("draft");
+            assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true))).isEnabled();
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard").setExact(true)).click();
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.getByText("Hello from Chromium", new Page.GetByTextOptions().setExact(true))).isVisible();
+        }
+    }
+}
